    const ev = good(); ev.lit.autopilot = ev.dark.autopilot.map((r) => ({ ...r })); ev.lit.law0 = ev.dark.autopilot.map((r) => ({ ...r })); const ev2 = good(); ev2.lit.autopilot = ev2.dark.autopilot.map((r, i) => ({ ...r, score: i === 7 ? r.score + 1e-9 : r.score })); ev2.lit.law0 = ev2.lit.autopilot.map((r) => ({ ...r }));
