    ok("!! a law outside the box (c 17, s -4.1), a champion outside it, 23 searches, none, three champions, a seed twice, a seed in the wrong group, 25 searches or five champions break LAWS INSIDE THE BOX; the box corner holds", [l1, l2, l3, l4, l5, l6, l7, l9, l10, l11].every((a) => names(a).includes("LAWS INSIDE THE BOX")) && !names(l8).includes("LAWS INSIDE THE BOX"));
    const d1 = good(); d1.range = { from: 25100, to: 25139 }; const d2 = good(); d2.range = { from: 25010, to: 25049 }; const d3 = good(); d3.range = { from: 25130, to: 25169 }; const d4 = good(); d4.range = { from: 25200, to: 25239 }; const d5 = good(); d5.range = { from: 25024, to: 25063 }; const d6 = good(); d6.range = { from: 25140, to: 25179 }; const d7 = good(); d7.range = { from: 25023, to: 25062 }; const d8 = good(); d8.range = { from: 25061, to: 25100 }; const d9 = good(); d9.range = { from: 24961, to: 25000 }; const d10 = good(); d10.range = { from: 25139, to: 25178 }; const d11 = good(); d11.range = { from: 25060, to: 25099 }; const d12 = good(); d12.range = { from: 24960, to: 24999 };
